package it.maleduclasse.audioflow;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;
import android.content.Context;
import android.widget.ImageView;

/** Compact official application artwork for the mobile top bar. */
final class BrandLogo {
  private static final String PHOTO="";
  static ImageView view(Context context){
    ImageView view=new ImageView(context);
    byte[] bytes=Base64.decode(PHOTO,Base64.DEFAULT);
    Bitmap bmp=BitmapFactory.decodeByteArray(bytes,0,bytes.length);
    view.setImageBitmap(bmp);
    view.setScaleType(ImageView.ScaleType.FIT_CENTER);
    view.setContentDescription("Logo Maleduclasse Audio Flow");
    return view;
  }
}
